-- Reference migration for the sync change log (`TomSqlSyncLog`).
--
-- Creates `tom_sync_change`, one row per change of an entity exposed for
-- offline sync, numbered within its collection, and `tom_sync_sequence`, the
-- counter each collection's numbers are taken from. This file is the canonical
-- DDL and is kept in sync with `syncChangeTable()` and `syncSequenceTable()` in
-- `lib/src/tomserver/sync/sync_sql.dart`; `test/framework_schema_test.dart`
-- replays this chain and compares the schema it builds against the
-- descriptors, so the two cannot drift apart.
--
-- Apply this file in the data source of each synced entity when the
-- application's database user is not permitted to run DDL, or when tenants
-- have a database or schema of their own, and configure the log with
-- `createSchema: false`.
--
-- Notes on the shape:
--
--  * `tenant` is '' outside tenancy.
--  * a change row holds the entity's id, its version after the change and
--    whether the change deleted it, never its values: a pull reads those
--    through the entity's repository, as the caller.
--  * a write records its change with `seq` NULL; a pull numbers the
--    committed changes in the order they were recorded (`id`), under the lock
--    of the collection's counter row, so a number a device has passed is
--    never given to a change that commits later.
CREATE TABLE IF NOT EXISTS tom_sync_change (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  tenant VARCHAR(32) NOT NULL,
  collection VARCHAR(64) NOT NULL,
  seq BIGINT NULL,
  entity_id VARCHAR(191) NOT NULL,
  version BIGINT NOT NULL,
  deleted SMALLINT NOT NULL DEFAULT 0,
  changed_at TIMESTAMP(6) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT uq_tom_sync_change_seq UNIQUE (tenant, collection, seq)
);

CREATE TABLE IF NOT EXISTS tom_sync_sequence (
  tenant VARCHAR(32) NOT NULL,
  collection VARCHAR(64) NOT NULL,
  last_sequence BIGINT NOT NULL,
  PRIMARY KEY (tenant, collection)
);
